def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    last_m, last_o = history[-1]

    op_d = 0
    for i in range(n):
        if history[i][1] == 'D':
            op_d += 1

    unprov = 0
    start_un = n - 11
    if start_un < 0:
        start_un = 0
    for i in range(start_un, n - 1):
        if history[i][0] == 'C' and history[i + 1][1] == 'D':
            unprov += 1

    if n >= 5:
        recent5_d = 0
        for i in range(n - 5, n):
            if history[i][1] == 'D':
                recent5_d += 1

        recent10_d = 0
        start10 = n - 10
        if start10 < 0:
            start10 = 0
        for i in range(start10, n):
            if history[i][1] == 'D':
                recent10_d += 1
    else:
        recent5_d = op_d
        recent10_d = op_d

    if last_o == 'D':
        if last_m == 'C':
            return 'D'

        run_dd = 0
        for i in range(n - 1, -1, -1):
            if history[i][0] == 'D' and history[i][1] == 'D':
                run_dd += 1
            else:
                break

        if run_dd >= 2 and n >= 5:
            if op_d * 3 <= n * 2 and recent5_d <= 4 and unprov <= 2:
                return 'C'
        return 'D'

    if unprov >= 4 and recent5_d >= 2:
        return 'D'

    if last_m == 'D':
        return 'C'

    if n >= 5:
        if op_d * 2 > n and recent10_d >= 4 and recent5_d >= 2:
            return 'D'

    return 'C'
